+        assert!((mean[i] - prior[i][2] / 0.04 * 0.1).abs() < 1e-14);
+        for j in 0..3 {
+            let expected = prior[i][j] - prior[i][2] * prior[2][j] / 0.04;
+            assert!((filter.pose_covariance()[i][j] - expected).abs() < 1e-14);
+        }
+    }
+}
